export const pages = ['home', 'about', 'services', 'venues', 'reviews', 'contacts', 'booking', 'privacy'];
export const filenames = {home:'index.html',about:'about.html',services:'services.html',venues:'venues.html',contacts:'contacts.html',reviews:'reviews.html',booking:'booking.html',privacy:'privacy.html'};
export const esc = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function safeUrl(value) {
  const s = String(value || '').trim();
  if (/^(https:\/\/|tel:\+?[\d ()-]+$)/i.test(s)) return esc(s);
  if (/^(assets|uploads)\/[a-zA-Z0-9_./-]+$/.test(s) && !s.includes('..')) return esc(s);
  return '#';
}
const image=(src,alt,cls='',eager=false)=> !src ? `<div class="photo-placeholder ${cls}" role="img" aria-label="${esc(alt)}"><span>ЛЕС</span><small>время вместе</small></div>` : `<img class="${cls}" src="${safeUrl(src)}" alt="${esc(alt)}" ${eager?'fetchpriority="high"':'loading="lazy"'} decoding="async" width="1280" height="852">`;
const button=(href,label,kind='primary',external=false)=>`<a class="button ${kind}" href="${href}" ${external?'target="_blank" rel="noopener noreferrer"':''}>${esc(label)}<span aria-hidden="true">↗</span></a>`;
const heading=(p)=>`<header class="page-heading"><p class="eyebrow">${esc(p.eyebrow)}</p><h1>${esc(p.title)} <em>${esc(p.titleAccent)}</em></h1><p class="lead">${esc(p.text)}</p></header>`;
function program(p,i,c){return `<article class="program-card" data-category="${esc(p.category)}"><a class="card-image" href="services.html#program-${i}">${image(p.image,p.imageAlt)}<span class="chip">${esc(p.category)}</span></a><div class="card-body"><p class="eyebrow">${esc(p.tag)}</p><h3 id="program-${i}">${esc(p.title)}</h3><p>${esc(p.description)}</p><div class="card-bottom"><span class="price">${esc(p.price||c.ui.priceUnknown)}${p.unit?`<small>${esc(p.unit)}</small>`:''}</span><a class="text-link" href="booking.html?program=${encodeURIComponent(p.id||p.title)}">${esc(c.ui.book)} <span aria-hidden="true">↗</span></a></div></div></article>`;}
function venue(v,c,large=false){return `<article class="venue ${large?'venue-large':''}">${image(v.image,v.imageAlt)}<div class="venue-content"><p class="eyebrow">${esc(v.district)}</p><h3>${esc(v.name)}</h3><p>${esc(large?v.description:v.address)}</p>${large?`<p class="address">${esc(v.address)}</p>${button(safeUrl(v.mapUrl),c.ui.map,'outline',true)}`:`<a class="text-link" href="venues.html">${esc(c.ui.details)} <span aria-hidden="true">↗</span></a>`}</div></article>`;}
const visible = items => items.filter(p=>p.visible!==false);
function cta(c){return `<section class="cta section"><div><p class="eyebrow">${esc(c.home.ctaLabel)}</p><h2>${esc(c.home.ctaTitle)}</h2></div><div><p>${esc(c.home.ctaText)}</p>${button('booking.html',c.ui.contact,'primary')}</div></section>`;}
export function main(c,page){
 if(page==='home') return `<section class="hero"><div class="hero-copy"><p class="eyebrow">${esc(c.home.eyebrow)}</p><h1>${esc(c.home.title)}<em>${esc(c.home.titleAccent)}</em></h1><p class="lead">${esc(c.home.text)}</p><div class="hero-buttons">${button('services.html',c.ui.programs)}<a class="quiet-link" href="about.html">${esc(c.ui.learn)}</a></div><span class="hero-location">${esc(c.brand.city)}</span></div><figure class="hero-photo">${image(c.home.image,c.home.imageAlt,'',true)}<figcaption>${esc(c.home.imageCaption)}</figcaption><div class="round-stamp" aria-hidden="true">${esc(c.home.stamp).replace(/\n/g,'<br>')}</div></figure></section><section class="stats" aria-label="Лес в цифрах">${c.home.stats.map(s=>`<div><strong>${esc(s.value)}</strong><span>${esc(s.label)}</span></div>`).join('')}</section><section class="intro section"><p class="eyebrow">${esc(c.home.introLabel)}</p><div><h2>${esc(c.home.introTitle)}</h2><p>${esc(c.home.introText)}</p></div></section><section class="section"><div class="section-top"><div><p class="eyebrow">${esc(c.home.programsLabel)}</p><h2>${esc(c.home.programsTitle)}</h2></div><a class="text-link" href="services.html">${esc(c.ui.allPrograms)} <span aria-hidden="true">↗</span></a></div><div class="program-grid">${c.programs.map((p,i)=>p.visible!==false&&p.featured?program(p,i,c):'').join('')}</div></section><section class="section"><div class="section-top"><div><p class="eyebrow">${esc(c.home.venuesLabel)}</p><h2>${esc(c.home.venuesTitle)}</h2></div></div><div class="venue-grid">${visible(c.venues).map(v=>venue(v,c)).join('')}</div></section>${videos(c)}${cta(c)}`;
 if(page==='about')return `${heading(c.about)}<div class="about-banner">${image(c.about.image,c.about.imageAlt,'',true)}</div><section class="intro section"><p class="eyebrow">${esc(c.brand.name)}</p><div><h2>${esc(c.about.storyTitle)}</h2><p>${esc(c.about.storyText)}</p></div></section><section class="values">${c.about.values.map((v,i)=>`<article><span class="index">0${i+1}</span><h3>${esc(v.title)}</h3><p>${esc(v.text)}</p></article>`).join('')}</section><section class="section"><h2>${esc(c.about.galleryTitle)}</h2><div class="gallery">${c.about.gallery.map(g=>`<a href="${safeUrl(g.image)}" target="_blank" rel="noopener noreferrer">${image(g.image,g.alt)}</a>`).join('')}</div></section>${cta(c)}`;
 if(page==='services')return `${heading(c.services)}<div class="filters" role="group" aria-label="Выбор программы"><button type="button" class="filter active" data-filter="all" aria-pressed="true">${esc(c.ui.all)}</button>${c.services.filters.map(f=>`<button type="button" class="filter" data-filter="${esc(f)}" aria-pressed="false">${esc(f)}</button>`).join('')}</div><div class="program-grid services-grid">${c.programs.map((p,i)=>p.visible!==false?program(p,i,c):'').join('')}</div><p class="empty-state" hidden role="status">${esc(c.ui.empty)}</p><p class="price-note">${esc(c.services.priceNote)}</p><section class="faq section"><h2>${esc(c.services.faqTitle)}</h2><div>${c.services.faqs.map(f=>`<details><summary>${esc(f.question)}<span aria-hidden="true">+</span></summary><p>${esc(f.answer)}</p></details>`).join('')}</div></section>${cta(c)}`;
 if(page==='venues')return `${heading(c.venuesPage)}<section class="venue-list">${visible(c.venues).map(v=>venue(v,c,true)).join('')}</section><section class="equipment section"><div><p class="eyebrow">${esc(c.brand.name)}</p><h2>${esc(c.venuesPage.equipmentTitle)}</h2><p>${esc(c.venuesPage.equipmentNote)}</p></div><ul>${c.venuesPage.equipment.map(e=>`<li>${esc(e)}</li>`).join('')}</ul></section>${cta(c)}`;
 if(page==='booking')return booking(c);
 if(page==='reviews')return reviews(c);
 if(page==='privacy')return `${heading(c.privacy)}<section class="privacy-copy section">${c.privacy.operator?`<p>${esc(c.privacy.operator)}</p>`:''}${c.privacy.sections.map(x=>`<article><h2>${esc(x.title)}</h2><p>${esc(x.text)}</p></article>`).join('')}</section>`;
 if(page==='contacts')return `${heading(c.contacts)}<section class="contact-grid"><div class="contact-card"><p class="eyebrow">${esc(c.contacts.phoneLabel)}</p><a class="contact-phone" href="${safeUrl(c.brand.phoneHref)}">${esc(c.brand.phone)}</a><p>${esc(c.brand.manager)}</p><a class="secondary-phone" href="${safeUrl(c.brand.phone2Href)}">${esc(c.brand.phone2)}</a>${button(safeUrl(c.brand.phoneHref),c.ui.call)}<div class="contact-vk"><p class="eyebrow">${esc(c.contacts.vkLabel)}</p><p>${esc(c.contacts.vkText)}</p>${button(safeUrl(c.brand.vk),c.ui.vk,'outline',true)}</div></div><aside class="contact-checklist"><h2>${esc(c.contacts.checklistTitle)}</h2><ol>${c.contacts.checklist.map(x=>`<li>${esc(x)}</li>`).join('')}</ol></aside></section><section class="section"><h2>${esc(c.contacts.locationTitle)}</h2><div class="contact-addresses">${visible(c.venues).map(v=>`<article><p class="eyebrow">${esc(v.district)}</p><h3>${esc(v.name)}</h3><p>${esc(v.address)}</p><a class="text-link" href="${safeUrl(v.mapUrl)}" target="_blank" rel="noopener noreferrer">${esc(c.ui.map)} ↗</a></article>`).join('')}</div></section>`;
 return '';
}
export function layout(c,page){return `<!doctype html><html lang="ru"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="theme-color" content="#fff5d7"><meta name="description" content="${esc(c.brand.description)}"><title>${esc(page==='home'?c.brand.name+' — '+c.brand.descriptor:c.ui.nav[page]+' — '+c.brand.name)}</title><link rel="icon" type="image/svg+xml" href="assets/favicon.svg"><link rel="stylesheet" href="assets/style.css"><script type="module" src="assets/app.mjs"></script></head><body data-page="${page}"><a class="skip" href="#main">${esc(c.ui.skip)}</a><header class="site-header"><a class="brand" href="index.html" aria-label="${esc(c.brand.name)} — ${esc(c.ui.nav.home)}"><strong>${esc(c.brand.name)}<span class="brand-dot" aria-hidden="true"></span></strong><span>${esc(c.brand.descriptor)}</span></a><button class="menu-toggle" type="button" aria-expanded="false" aria-controls="navigation">${esc(c.ui.menu)}<span aria-hidden="true">☰</span></button><nav id="navigation" aria-label="Основная навигация">${pages.filter(p=>!['home','privacy','booking'].includes(p)).map(p=>`<a href="${filenames[p]}" ${p===page?'aria-current="page"':''}>${esc(c.ui.nav[p])}</a>`).join('')}</nav><a class="header-contact" href="booking.html">${esc(c.ui.contact)} ↗</a></header><main id="main">${main(c,page)}</main><footer class="site-footer"><div class="footer-top"><div><a class="brand" href="index.html"><strong>${esc(c.brand.name)}<span class="brand-dot" aria-hidden="true"></span></strong><span>${esc(c.brand.descriptor)}</span></a><p>${esc(c.brand.footerText)}</p></div><div class="footer-nav">${pages.filter(p=>!['home','privacy','booking'].includes(p)).map(p=>`<a href="${filenames[p]}">${esc(c.ui.nav[p])}</a>`).join('')}</div><div class="footer-contact"><a href="${safeUrl(c.brand.phoneHref)}">${esc(c.brand.phone)}</a><a href="${safeUrl(c.brand.phone2Href)}">${esc(c.brand.phone2)}</a><span>${esc(c.brand.manager)}</span><a href="${safeUrl(c.brand.vk)}" target="_blank" rel="noopener noreferrer">${esc(c.ui.vk)} ↗</a></div></div><div class="footer-addresses">${visible(c.venues).map(v=>`<span>${esc(v.name)} · ${esc(v.address)}</span>`).join('')}</div><div class="footer-bottom"><span>© ${new Date().getFullYear()} ${esc(c.brand.copyright)}</span><a href="privacy.html">${esc(c.ui.privacy)}</a><a href="admin.html">${esc(c.ui.admin)}</a></div></footer></body></html>`;}

function videos(c){return `<section class="section"><div class="section-top"><h2>${esc(c.videos.title)}</h2></div>${c.videos.items.length?`<div class="video-grid">${c.videos.items.filter(x=>x.visible!==false).map(x=>`<article><video controls playsinline preload="none" ${x.poster?`poster="${safeUrl(x.poster)}"`:''} src="${safeUrl(x.url)}"></video><h3>${esc(x.title)}</h3></article>`).join('')}</div>`:`<div class="media-empty"><span class="play-sign" aria-hidden="true">▷</span><p>${esc(c.videos.text)}</p></div>`}</section>`;}
function reviews(c){return `${heading(c.reviews)}<section class="section reviews-grid">${c.reviews.items.filter(x=>x.visible!==false).map(x=>`<article class="review"><p>${esc(x.text)}</p><footer><strong>${esc(x.name)}</strong><span>${esc(x.date)}</span>${x.url?`<a class="text-link" href="${safeUrl(x.url)}" target="_blank" rel="noopener noreferrer">ВКонтакте ↗</a>`:''}</footer></article>`).join('')||`<div class="media-empty"><p>${esc(c.reviews.empty)}</p></div>`}</section><div class="section">${button(safeUrl(c.brand.vk),c.reviews.linkText,'outline',true)}</div>${cta(c)}`;}
function booking(c){const b=c.booking;return `${heading(b)}<section class="booking-layout"><form id="booking-form" class="booking-form"><div class="form-grid"><label>${esc(b.programLabel)}<select name="program" required><option value="">${esc(b.selectLabel)}</option>${visible(c.programs).map(p=>`<option value="${esc(p.id)}">${esc(p.title)}</option>`).join('')}</select></label><label>${esc(b.venueLabel)}<select name="venue" required><option value="">${esc(b.selectLabel)}</option>${visible(c.venues).map(v=>`<option value="${esc(v.id)}">${esc(v.name)}</option>`).join('')}</select></label><label>${esc(b.dateLabel)}<input type="date" name="date" required></label><label>${esc(b.timeLabel)}<input type="time" name="time" required></label><label>${esc(b.nameLabel)}<input name="name" autocomplete="given-name" maxlength="100" required></label><label>${esc(b.phoneLabel)}<input name="phone" type="tel" autocomplete="tel" maxlength="25" required placeholder="+7 …"></label><label>${esc(b.peopleLabel)}<input name="people" type="number" min="1" max="200" required></label></div><label>${esc(b.commentLabel)}<textarea name="comment" rows="3" maxlength="1500"></textarea></label><div class="honeypot" aria-hidden="true"><label>Website<input name="website" tabindex="-1" autocomplete="off"></label></div><label class="consent"><input name="consent" type="checkbox" required><span>${esc(b.consentLabel)}. <a href="privacy.html" target="_blank" rel="noopener noreferrer">${esc(c.ui.privacy)}</a></span></label><button class="button primary" type="submit" disabled>${esc(b.submitLabel)}</button><p id="booking-status" role="status" aria-live="polite">${esc(b.offlineText)}</p></form><aside class="booking-aside"><p class="eyebrow">${esc(c.brand.name)}</p><h2>${esc(c.home.ctaTitle)}</h2><p>${esc(b.note)}</p><a class="contact-phone" href="${safeUrl(c.brand.phoneHref)}">${esc(c.brand.phone)}</a><a href="${safeUrl(c.brand.phone2Href)}">${esc(c.brand.phone2)}</a>${button(safeUrl(c.brand.vk),c.ui.vk,'outline',true)}</aside></section><script id="booking-config" type="application/json">${JSON.stringify({apiBase:c.settings.apiBase,privacyReady:c.privacy.ready,labels:b}).replace(/</g,'\u003c')}</script>`;}
